import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { ShipClass } from '../sim/types';

export type ModelClass = ShipClass | 'pirate';

/** Foundry fleet files in `public/models`, generated by `scripts/blender/build_fleet.py`. */
export const SHIP_MODEL: Record<ModelClass, string> = {
  drone: 'foundry_drone',
  scout: 'foundry_scout',
  fighter: 'foundry_fighter',
  hauler: 'foundry_hauler',
  barge: 'foundry_barge',
  harvester: 'foundry_harvester',
  repair: 'foundry_repair',
  pirate: 'foundry_pirate',
};
export const CARRIER_MODEL = 'foundry_carrier';
/** Kenney Space Kit (CC0); see the README in `public/models`. */
export const ASTEROID_MODEL = 'meteor';

/** Hull length in world units, matching the old placeholder sizes. */
export const SHIP_LENGTH: Record<ModelClass, number> = {
  drone: 2.2,
  scout: 2.9,
  fighter: 3.2,
  hauler: 4.5,
  barge: 7,
  harvester: 4.8,
  repair: 2.4,
  pirate: 3.5,
};

/** Resolved against Vite's base, so it works under `/asteroid-fleet/` on Pages. */
export function modelUrl(name: string): string {
  return `${import.meta.env.BASE_URL}models/${name}.glb`;
}

/** The kit's accent material; recoloured per class so classes stay readable. */
const ACCENT = 'metalRed';

/**
 * Bakes a glTF scene into one geometry with vertex colours, so each class is a
 * single instanced draw call. Centred, nose on +Z, scaled to `length` along Z
 * (or to a unit radius when `length` is omitted).
 */
export function bakeModel(
  scene: THREE.Object3D,
  accent?: THREE.ColorRepresentation,
  length?: number,
): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const accentColor = accent === undefined ? null : new THREE.Color(accent);
  scene.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (!mesh.isMesh) return;
    const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    const src = mesh.geometry;
    const groups = src.groups.length
      ? src.groups
      : [{ start: 0, count: Infinity, materialIndex: 0 }];
    const flat = src.index ? src.toNonIndexed() : src.clone();
    const total = flat.getAttribute('position').count;
    for (const grp of groups) {
      const mat = mats[grp.materialIndex ?? 0] as THREE.MeshStandardMaterial;
      const c = accentColor && mat.name === ACCENT ? accentColor : mat.color;
      const end = Math.min(total, grp.start + grp.count);
      const g = new THREE.BufferGeometry();
      for (const name of ['position', 'normal'] as const) {
        const a = flat.getAttribute(name) as THREE.BufferAttribute;
        g.setAttribute(name, new THREE.BufferAttribute(a.array.slice(grp.start * 3, end * 3), 3));
      }
      const col = new Float32Array((end - grp.start) * 3);
      for (let i = 0; i < col.length; i += 3) col.set([c.r, c.g, c.b], i);
      g.setAttribute('color', new THREE.BufferAttribute(col, 3));
      parts.push(g);
    }
    flat.dispose();
  });
  const g = mergeGeometries(parts) ?? new THREE.BufferGeometry();
  for (const p of parts) p.dispose();
  g.computeBoundingBox();
  const box = g.boundingBox!;
  const center = box.getCenter(new THREE.Vector3());
  g.translate(-center.x, -center.y, -center.z);
  const size = box.getSize(new THREE.Vector3());
  const k = length ? length / size.z : 2 / Math.max(size.x, size.y, size.z);
  g.scale(k, k, k);
  g.computeBoundingSphere();
  return g;
}

/** Carrier hull length in world units, matching the old box hull. */
export const CARRIER_LENGTH = 20;

/**
 * A drawable copy of the carrier glTF: centred, nose on +Z, `CARRIER_LENGTH` long. Unlike
 * the ships it is not baked, so it keeps one draw call per material and its `glow` parts
 * draw unlit and bright enough for bloom. `tint` multiplies the main hull colour, to tell
 * other carriers apart.
 */
export function carrierModel(scene: THREE.Object3D, tint?: THREE.ColorRepresentation): THREE.Group {
  const root = scene.clone(true);
  const box = new THREE.Box3().setFromObject(root);
  const k = CARRIER_LENGTH / box.getSize(new THREE.Vector3()).z;
  const center = box.getCenter(new THREE.Vector3());
  root.position.copy(center).multiplyScalar(-k);
  root.scale.setScalar(k);
  const tintColor = tint === undefined ? null : new THREE.Color(tint);
  root.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (!mesh.isMesh) return;
    const src = mesh.material as THREE.MeshStandardMaterial;
    if (src.name === 'glow') {
      mesh.material = new THREE.MeshBasicMaterial({
        color: src.color.clone().multiplyScalar(3),
        toneMapped: false,
      });
      return;
    }
    const color = src.color.clone();
    if (tintColor && src.name === 'hull') color.multiply(tintColor);
    mesh.material = new THREE.MeshStandardMaterial({
      color,
      metalness: 0.45,
      roughness: 0.6,
      flatShading: true,
    });
  });
  const group = new THREE.Group();
  group.add(root);
  return group;
}

/** Frees the materials `carrierModel` made; the geometry stays shared with the glTF cache. */
export function disposeCarrierModel(model: THREE.Object3D): void {
  model.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (mesh.isMesh) (mesh.material as THREE.Material).dispose();
  });
}
